1	import { db } from "@/lib/db";
2	import { MICROS_PER_CREDIT } from "@/lib/credits";
3	
4	// Aggregations for /dashboard/usage. Everything here is derived from rows that
5	// already exist — CreditLedger and Build — with no schema change and no
6	// estimate. If a number cannot be computed from those two tables it is not in
7	// this file, and the page says so instead of inventing it.
8	//
9	// Deliberately absent, because nothing measures them: storage, bandwidth,
10	// request counts, seats, and anything resembling a plan allowance.
11	//
12	// COST BASIS IS NOT EXPOSED. Build.costMicros is our real model spend, which is
13	// the cost side of the retail prices in lib/stripe.ts. Every figure this module
14	// returns is in CREDITS; costMicros is only ever used inside an arithmetic
15	// comparison against what was charged, never returned as money.
16	
17	const MS_DAY = 24 * 60 * 60 * 1000;
18	
19	/** Epoch ms for the start of the UTC calendar day containing `d`. */
20	function utcDayStart(d: Date): number {
21	  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
22	}
23	
24	export type DayBucket = {
25	  /** Start of the UTC day, epoch ms. */
26	  ts: number;
27	  credits: number;
28	};
29	
30	/**
31	 * Credits spent per UTC calendar day over the last `days` days, today included.
32	 *
33	 * NOTE the deliberate mismatch with spentInWindow() in lib/credits.ts: that one
34	 * measures a rolling window to the millisecond because it is what the spend cap
35	 * enforces. A chart cannot have a half-day bucket at its left edge, so this
36	 * snaps to UTC day boundaries. The two totals can therefore differ by up to one
37	 * day's spend, and the page says so rather than presenting them as the same
38	 * number twice.
39	 *
40	 * Row count is bounded by one user's charges in 90 days, so bucketing in JS
41	 * beats a raw SQL date_trunc that would have to be written per-dialect.
42	 */
43	export async function dailySpend(userId: string, days: number): Promise<DayBucket[]> {
44	  const firstDay = utcDayStart(new Date()) - (days - 1) * MS_DAY;
45	
46	  const rows = await db.creditLedger.findMany({
47	    where: { userId, delta: { lt: 0 }, createdAt: { gte: new Date(firstDay) } },
48	    select: { createdAt: true, delta: true },
49	  });
50	
51	  const buckets: DayBucket[] = Array.from({ length: days }, (_, i) => ({
52	    ts: firstDay + i * MS_DAY,
53	    credits: 0,
54	  }));
55	
56	  for (const row of rows) {
57	    const index = Math.round((utcDayStart(row.createdAt) - firstDay) / MS_DAY);
58	    // Defensive: a DST-free UTC calculation should never land outside the
59	    // array, but a clock skew between Postgres and this process could. A bar
60	    // silently written past the end of the chart is worse than a dropped one.
61	    if (index >= 0 && index < days) {
62	      buckets[index].credits += Math.abs(row.delta);
63	    }
64	  }
65	
66	  return buckets;
67	}
68	
69	export type SiteUsage = {
70	  projectId: string;
71	  name: string;
72	  credits: number;
73	  builds: number;
74	  lastAt: Date;
75	};
76	
77	/**
78	 * Credits charged, grouped by the website they were charged for.
79	 *
80	 * Attribution is real, not inferred: CreditLedger.buildId -> Build.projectId.
81	 * This groups the Build side because it also carries the build count and the
82	 * last-charged date, which the ledger alone does not.
83	 *
84	 * IT CANNOT SEE DELETED SITES. Project deletion cascades its builds away and
85	 * SET NULLs CreditLedger.buildId (prisma/schema.prisma), so the charge survives
86	 * on the statement with nothing attached. The caller reconciles this total
87	 * against the ledger and shows the difference explicitly — see the page.
88	 */
89	export async function siteUsage(userId: string): Promise<SiteUsage[]> {
90	  const grouped = await db.build.groupBy({
91	    by: ["projectId"],
92	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
93	    _sum: { creditsCharged: true },
94	    _count: true,
95	    _max: { createdAt: true },
96	  });
97	
98	  if (grouped.length === 0) return [];
99	
100	  const projects = await db.project.findMany({
101	    where: { id: { in: grouped.map((g) => g.projectId) }, userId },
102	    select: { id: true, name: true },
103	  });
104	  const nameById = new Map(projects.map((p) => [p.id, p.name]));
105	
106	  const rows: SiteUsage[] = [];
107	  for (const g of grouped) {
108	    const name = nameById.get(g.projectId);
109	    const lastAt = g._max.createdAt;
110	    // A group with no matching project, or no date, means the read raced a
111	    // delete. Drop it rather than rendering a row with a placeholder name — the
112	    // reconciliation below folds it into the deleted-sites total instead, which
113	    // is where it honestly belongs.
114	    if (name === undefined || lastAt === null) continue;
115	    rows.push({
116	      projectId: g.projectId,
117	      name,
118	      credits: g._sum.creditsCharged ?? 0,
119	      builds: g._count,
120	      lastAt,
121	    });
122	  }
123	
124	  return rows.sort((a, b) => b.credits - a.credits || a.name.localeCompare(b.name));
125	}
126	
127	export type NotCharged = {
128	  failedBuilds: number;
129	  repairedBuilds: number;
130	  /** Credits the repair rule absorbed. Conservative — see below. */
131	  repairWaivedCredits: number;
132	};
133	
134	/**
135	 * The two things Kodely records but never bills: failed builds and repair
136	 * passes. Both are rules 3 and 4 of the contract in lib/credits.ts, restated as
137	 * arithmetic on this user's own rows.
138	 *
139	 * The waived figure is DERIVED, exactly as lib/credits.ts says it can be:
140	 * repairAttempts > 0 together with costMicros > creditsCharged * MICROS_PER_CREDIT
141	 * is "this run was repaired and we absorbed the difference".
142	 *
143	 * It understates on purpose. creditsCharged is rounded UP from the billable
144	 * attempt, so charging-side micros are overstated and the derived difference
145	 * comes out low. On a page whose entire point is not overclaiming, a saving
146	 * quoted slightly under the truth is the only acceptable rounding direction.
147	 */
148	export async function notCharged(userId: string): Promise<NotCharged> {
149	  const [failedBuilds, repaired] = await Promise.all([
150	    db.build.count({ where: { project: { userId }, status: "FAILED" } }),
151	    db.build.aggregate({
152	      where: { project: { userId }, status: "SUCCEEDED", repairAttempts: { gt: 0 } },
153	      _count: true,
154	      _sum: { costMicros: true, creditsCharged: true },
155	    }),
156	  ]);
157	
158	  const trueMicros = repaired._sum.costMicros ?? 0;
159	  const chargedMicros = (repaired._sum.creditsCharged ?? 0) * MICROS_PER_CREDIT;
160	
161	  return {
162	    failedBuilds,
163	    repairedBuilds: repaired._count,
164	    repairWaivedCredits: Math.max(0, Math.floor((trueMicros - chargedMicros) / MICROS_PER_CREDIT)),
165	  };
166	}
167	
168	export type LedgerTotals = {
169	  /** Every positive delta: the signup grant, paid top-ups, social rewards. */
170	  added: number;
171	  /** Every negative delta. Today only chargeForBuild writes one. */
172	  spent: number;
173	};
174	
175	export async function ledgerTotals(userId: string): Promise<LedgerTotals> {
176	  const [credited, debited] = await Promise.all([
177	    db.creditLedger.aggregate({ where: { userId, delta: { gt: 0 } }, _sum: { delta: true } }),
178	    db.creditLedger.aggregate({ where: { userId, delta: { lt: 0 } }, _sum: { delta: true } }),
179	  ]);
180	  return {
181	    added: credited._sum.delta ?? 0,
182	    spent: Math.abs(debited._sum.delta ?? 0),
183	  };
184	}
