1	import { EmptyState } from "@/components/ui/EmptyState";
2	import { formatCredits } from "../billing/ledger";
3	import type { DayBucket } from "./data";
4	
5	/* Credits spent per day, drawn by hand.
6	   ───────────────────────────────────────────────────────────────────────────
7	   NO CHARTING DEPENDENCY. This is plain SVG in a Server Component: it ships no
8	   JavaScript at all, which for a static bar chart is not a compromise — it is
9	   the better answer.
10	
11	   THEMING. Every colour is a Tailwind class bound to a design token
12	   (`fill-brand`, `stroke-hair`, `fill-ink-3`), never an attribute and never a
13	   hex, so light and dark are handled by the same variable swap as the rest of
14	   the product. Presentational SVG attributes lose to CSS, which is why the
15	   classes work at all.
16	
17	   ACCESSIBILITY. Three channels, in order of who they serve:
18	     1. A prose summary above the chart — the shape of the data in a sentence,
19	        for everyone including people who skim.
20	     2. The <svg> is role="img" with an aria-label carrying that same summary,
21	        so a screen reader gets the gist instead of 30 unlabelled <rect>s.
22	     3. A real <table> in a <details>, keyboard-operable, carrying every figure
23	        the bars encode. The bars are not individually focusable BECAUSE the
24	        table exists: 30 tab stops that each announce one number is worse than
25	        one tab stop that opens all of them.
26	   The chart is also legible at any width — it scales uniformly with its
27	   viewBox, so no label is ever clipped or squashed. */
28	
29	const AXIS_DATE = new Intl.DateTimeFormat("en-GB", {
30	  day: "numeric",
31	  month: "short",
32	  timeZone: "UTC",
33	});
34	
35	const FULL_DATE = new Intl.DateTimeFormat("en-GB", {
36	  weekday: "short",
37	  day: "2-digit",
38	  month: "short",
39	  year: "numeric",
40	  timeZone: "UTC",
41	});
42	
43	/** Round a peak up to a round number so the top gridline reads as a real
44	    quantity ("500") rather than as the maximum sample ("472"). */
45	function niceCeiling(peak: number): number {
46	  if (peak <= 0) return 1;
47	  const magnitude = 10 ** Math.floor(Math.log10(peak));
48	  for (const step of [1, 1.5, 2, 2.5, 5, 10]) {
49	    const candidate = step * magnitude;
50	    if (candidate >= peak) return Math.ceil(candidate);
51	  }
52	  return Math.ceil(10 * magnitude);
53	}
54	
55	// User-space geometry. The SVG scales uniformly to its container, so these are
56	// proportions rather than pixels.
57	const W = 720;
58	const H = 210;
59	const PAD_L = 48;
60	const PAD_R = 10;
61	const PAD_T = 12;
62	const PAD_B = 30;
63	const PLOT_W = W - PAD_L - PAD_R;
64	const PLOT_H = H - PAD_T - PAD_B;
65	
66	export function UsageChart({ buckets, days }: { buckets: DayBucket[]; days: number }) {
67	  const total = buckets.reduce((sum, b) => sum + b.credits, 0);
68	
69	  if (total === 0 || buckets.length === 0) {
70	    return (
71	      <EmptyState
72	        className="mt-5"
73	        kind="empty"
74	        title={`No credits spent in the last ${days} days`}
75	        body="Nothing has been charged to your account in this window. A build only reaches this chart once it has succeeded and had measured model cost — failed builds are free and never appear."
76	      />
77	    );
78	  }
79	
80	  const activeDays = buckets.filter((b) => b.credits > 0).length;
81	  const peak = buckets.reduce((best, b) => (b.credits > best.credits ? b : best), buckets[0]);
82	  const max = niceCeiling(peak.credits);
83	
84	  const summary =
85	    `Credits spent per day over the last ${days} days. ` +
86	    `${formatCredits(total)} credits in total across ${activeDays} ` +
87	    `${activeDays === 1 ? "day" : "days"} with any spend. ` +
88	    `The heaviest day was ${FULL_DATE.format(new Date(peak.ts))} at ` +
89	    `${formatCredits(peak.credits)} credits.`;
90	
91	  const slot = PLOT_W / buckets.length;
92	  const barW = Math.max(2, Math.min(18, slot * 0.62));
93	
94	  // Three gridlines is the most a 170-unit-tall plot can carry without the
95	  // labels becoming the loudest thing in it.
96	  const gridValues = [0, max / 2, max];
97	
98	  // Four x labels, evenly spaced and always including both ends, so the reader
99	  // can date any bar by interpolation without 30 overlapping labels.
100	  const last = buckets.length - 1;
101	  const tickIndexes = Array.from(
102	    new Set([0, Math.round(last / 3), Math.round((2 * last) / 3), last]),
103	  ).filter((i) => i >= 0 && i <= last);
104	
105	  const y = (value: number) => PAD_T + PLOT_H * (1 - value / max);
106	
107	  return (
108	    <figure className="mt-5">
109	      <figcaption className="text-sm leading-relaxed text-ink-2">
110	        <span className="k-num font-medium text-ink">{formatCredits(total)}</span> credits over the
111	        last <span className="k-num font-medium text-ink">{days}</span> days, across{" "}
112	        <span className="k-num font-medium text-ink">{activeDays}</span>{" "}
113	        {activeDays === 1 ? "day" : "days"} with any spend. Heaviest day:{" "}
114	        <span className="k-num font-medium text-ink">{formatCredits(peak.credits)}</span> credits on{" "}
115	        {FULL_DATE.format(new Date(peak.ts))}.
116	      </figcaption>
117	
118	      <svg
119	        role="img"
120	        aria-label={summary}
121	        viewBox={`0 0 ${W} ${H}`}
122	        className="mt-4 h-auto w-full"
123	      >
124	        {gridValues.map((value) => (
125	          <g key={value}>
126	            <line
127	              x1={PAD_L}
128	              x2={W - PAD_R}
129	              y1={y(value)}
130	              y2={y(value)}
131	              className={value === 0 ? "stroke-line-mid" : "stroke-hair"}
132	              strokeWidth={1}
133	            />
134	            <text
135	              x={PAD_L - 8}
136	              y={y(value) + 3.5}
137	              textAnchor="end"
138	              fontSize={10}
139	              className="k-num fill-ink-3"
140	            >
141	              {formatCredits(Math.round(value))}
142	            </text>
143	          </g>
144	        ))}
145	
146	        {buckets.map((b, i) => {
147	          if (b.credits <= 0) return null;
148	          // A one-unit floor so a real but tiny day is a visible mark rather
149	          // than a gap indistinguishable from a day with no spend at all.
150	          const height = Math.max(1.5, (b.credits / max) * PLOT_H);
151	          return (
152	            <rect
153	              key={b.ts}
154	              x={PAD_L + slot * (i + 0.5) - barW / 2}
155	              y={PAD_T + PLOT_H - height}
156	              width={barW}
157	              height={height}
158	              rx={1.5}
159	              className="fill-brand"
160	            />
161	          );
162	        })}
163	
164	        {tickIndexes.map((i) => (
165	          <text
166	            key={buckets[i].ts}
167	            x={PAD_L + slot * (i + 0.5)}
168	            y={H - 10}
169	            textAnchor={i === 0 ? "start" : i === last ? "end" : "middle"}
170	            fontSize={10}
171	            className="k-num fill-ink-3"
172	          >
173	            {AXIS_DATE.format(new Date(buckets[i].ts))}
174	          </text>
175	        ))}
176	      </svg>
177	
178	      <details className="mt-4">
179	        <summary className="k-focus inline-flex cursor-pointer rounded-sm text-[0.8125rem] font-medium text-ink-2 hover:text-ink">
180	          Show these <span className="k-num">{activeDays}</span>{" "}
181	          {activeDays === 1 ? "day" : "days"} as a table
182	        </summary>
183	        <div className="k-scroll-x mt-3 rounded-lg border border-hair">
184	          <table className="w-full text-left text-sm">
185	            <caption className="sr-only">
186	              Credits spent per UTC day over the last {days} days. Days with no spend are omitted.
187	            </caption>
188	            <thead>
189	              <tr className="border-b border-hair">
190	                <th scope="col" className="k-label px-4 py-2.5 font-semibold">
191	                  Day (UTC)
192	                </th>
193	                <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
194	                  Credits
195	                </th>
196	              </tr>
197	            </thead>
198	            <tbody className="divide-y divide-hair">
199	              {buckets
200	                .filter((b) => b.credits > 0)
201	                .reverse()
202	                .map((b) => (
203	                  <tr key={b.ts}>
204	                    <td className="k-num px-4 py-2.5 whitespace-nowrap text-ink-2">
205	                      {FULL_DATE.format(new Date(b.ts))}
206	                    </td>
207	                    <td className="k-num px-4 py-2.5 text-right font-medium whitespace-nowrap text-ink">
208	                      {formatCredits(b.credits)}
209	                    </td>
210	                  </tr>
211	                ))}
212	            </tbody>
213	          </table>
214	        </div>
215	        <p className="mt-2 text-xs text-ink-3">
216	          Days with no spend are left out — <span className="k-num">{days - activeDays}</span> of
217	          the last <span className="k-num">{days}</span>.
218	        </p>
219	      </details>
220	    </figure>
221	  );
222	}
