1	import { PLATFORM_LABELS } from "@/app/api/rewards/_lib";
2	
3	// Presentation helpers for the customer's own credit statement.
4	//
5	// The admin equivalent (app/admin/users/ui.tsx `reasonLabel`) decodes the same
6	// strings, but it is allowed to fall back to echoing the raw `reason` and to
7	// expose it on hover. This one is not. `CreditLedger.reason` is free text that
8	// carries a Stripe Checkout session id and an HMAC of a customer's external
9	// social account (see app/api/rewards/_lib.ts), and neither of those belongs in
10	// front of the person they are about. So every branch here returns wording we
11	// wrote, and the unknown branch returns wording too — it never passes the
12	// string through.
13	
14	export type ReasonDescription = {
15	  /** Plain-English label for the "What" column. */
16	  label: string;
17	  /** Optional second line. Never contains an id, session or hash. */
18	  detail?: string;
19	};
20	
21	/**
22	 * Decode one ledger `reason` into something a customer can read.
23	 *
24	 * The four shapes that exist today, all written by our own code:
25	 *   "build"                                     a charge for a successful build
26	 *   "signup_grant"                              the free credits at signup
27	 *   "stripe:<checkout session id>"              a paid top-up (webhook only)
28	 *   "reward:<platform>:<hash>"                  a granted social reward
29	 *   "reward:<platform>:pending:<hash>"          a claim on hold, delta 0
30	 */
31	export function describeReason(reason: string, delta: number): ReasonDescription {
32	  if (reason === "build") {
33	    return { label: "Site build" };
34	  }
35	
36	  if (reason === "signup_grant") {
37	    return { label: "Welcome credits", detail: "Added free when you created your account" };
38	  }
39	
40	  if (reason.startsWith("stripe:")) {
41	    // Everything after the prefix is the Stripe Checkout session id. It
42	    // identifies a payment session, is meaningless to the customer, and stops
43	    // here. The pack size is already visible in the Change column.
44	    return { label: "Credit purchase", detail: "Paid top-up" };
45	  }
46	
47	  if (reason.startsWith("reward:")) {
48	    const parts = reason.split(":");
49	    // Platform name only — the trailing segment is a keyed hash of the external
50	    // account and is never rendered.
51	    const name = (PLATFORM_LABELS as Record<string, string | undefined>)[parts[1] ?? ""] ?? "Social";
52	
53	    if (parts[2] === "pending") {
54	      // A zero-delta row: the claim is recorded but nothing has moved yet.
55	      return {
56	        label: `${name} reward — on hold`,
57	        detail: "Recorded. The credits are added once the hold period is up.",
58	      };
59	    }
60	    return { label: `${name} reward` };
61	  }
62	
63	  // Unrecognised shape. `reason` is free text on an append-only table, so it
64	  // could be anything — including something with an id in it. Describe it from
65	  // the direction of the money instead of echoing it.
66	  if (delta > 0) return { label: "Credits added" };
67	  if (delta < 0) return { label: "Credits used" };
68	  return { label: "Account note" };
69	}
70	
71	// Fixed to UTC so the string is the same on every render and does not depend on
72	// the server's timezone. Rendered server-side only, so there is no client clock
73	// to disagree with it.
74	const DAY = new Intl.DateTimeFormat("en-GB", {
75	  day: "2-digit",
76	  month: "short",
77	  year: "numeric",
78	  timeZone: "UTC",
79	});
80	
81	const TIME = new Intl.DateTimeFormat("en-GB", {
82	  hour: "2-digit",
83	  minute: "2-digit",
84	  hour12: false,
85	  timeZone: "UTC",
86	});
87	
88	export function formatDay(d: Date): string {
89	  return DAY.format(d);
90	}
91	
92	export function formatTime(d: Date): string {
93	  return TIME.format(d);
94	}
95	
96	/** "+750" / "-472" / "0" — the sign is the whole point of a statement column. */
97	export function signedCredits(delta: number): string {
98	  return delta > 0 ? `+${delta.toLocaleString("en-GB")}` : delta.toLocaleString("en-GB");
99	}
100	
101	export function formatCredits(n: number): string {
102	  return n.toLocaleString("en-GB");
103	}
104	
105	// RETAIL ONLY. This formats CreditPack.priceUsdCents — the published price of a
106	// pack, which the customer is about to be charged and which already appears in
107	// CreditPack.label. It must never be pointed at Build.costMicros: that figure
108	// is our underlying model spend, i.e. the cost basis behind those prices (see
109	// the margin table in lib/stripe.ts), and it is not the customer's business.
110	const USD = new Intl.NumberFormat("en-US", {
111	  style: "currency",
112	  currency: "USD",
113	  minimumFractionDigits: 0,
114	  maximumFractionDigits: 2,
115	});
116	
117	export function formatUsdCents(cents: number): string {
118	  return USD.format(cents / 100);
119	}
