5	export type SegmentOption<T extends string> = {
6	  value: T;
7	  label: string;
8	  /** When set, the label is hidden and this is the accessible name — used by
9	      the grid/list and device toggles, which are icon-only by convention. */
10	  iconOnly?: boolean;
11	  icon?: ReactNode;
12	};
13	
14	/* A radio group wearing a segmented control's clothes. Real radios, not
15	   buttons: arrow-key navigation between options and single-tab-stop
16	   behaviour are what the customer's keyboard already expects from a
17	   this-or-that choice, and neither comes free with <button>. */
18	export function Segmented<T extends string>({
19	  name,
20	  value,
21	  onChange,
22	  options,
23	  size = "md",
24	  className = "",
25	  ariaLabel,
26	}: {
27	  name: string;
28	  value: T;
29	  onChange: (v: T) => void;
30	  options: SegmentOption<T>[];
31	  size?: "sm" | "md";
32	  className?: string;
33	  ariaLabel: string;
34	}) {
35	  const h = size === "sm" ? "h-7" : "h-8";
36	  return (
37	    <div
38	      role="radiogroup"
39	      aria-label={ariaLabel}
40	      className={`inline-flex items-center gap-0.5 rounded-md border border-hair bg-surface-2 p-0.5 ${className}`}
41	    >
42	      {options.map((o) => {
43	        const active = o.value === value;
44	        return (
45	          <label
46	            key={o.value}
47	            title={o.iconOnly ? o.label : undefined}
48	            className={[
49	              // k-focus-within, not a hand-rolled has-[:focus-visible] chain:
50	              // the radio is sr-only so the label never matches :focus-visible
51	              // itself, but the RING must still be the product's one ring. See
52	              // the note beside both rules in app/globals.css.
53	              "k-focus-within relative inline-flex cursor-pointer items-center justify-center gap-1.5 rounded-xs px-2.5 text-[0.8125rem] font-medium",
54	              h,
55	              active ? "bg-surface text-ink shadow-e1" : "text-ink-2 hover:text-ink",
56	              "transition-colors duration-[var(--t-1)]",
57	            ].join(" ")}
58	          >
59	            <input
60	              type="radio"
61	              name={name}
62	              value={o.value}
63	              checked={active}
64	              onChange={() => onChange(o.value)}
65	              className="sr-only"
66	            />
67	            {o.icon}
68	            {o.iconOnly ? <span className="sr-only">{o.label}</span> : o.label}
69	          </label>
70	        );
71	      })}
72	    </div>
73	  );
