429	/* Scroll entrance for the hero mock (HeroMock.tsx). A CSS transition
430	   toggled by an `is-entered` class from an IntersectionObserver — no
431	   dependence on framer-motion's in-view scheduling, which applied its
432	   initial styles here but never actually triggered. */
433	@keyframes hero-mock-in {
434	  from {
435	    opacity: 0;
436	    transform: translateY(56px) scale(0.94);
437	  }
438	  to {
439	    opacity: 1;
440	    transform: translateY(0) scale(1);
441	  }
442	}
443	
444	/* Fallback for browsers without scroll-driven animation support: play the
445	   entrance once on load. Not as nice as scroll-linked, but never leaves
446	   the mock stuck invisible. */
447	.hero-mock-enter {
448	  animation: hero-mock-in 0.9s cubic-bezier(0.16, 1, 0.3, 1) both;
449	}
450	
451	/* The real thing: a native scroll-driven animation, progressed by the
452	   element's own position in the viewport. No IntersectionObserver, no
453	   scroll listener, no React state — every JS-based trigger tried here
454	   (framer's whileInView, a raw IntersectionObserver, a scroll listener)
455	   failed to fire in practice, and this removes that entire class of
456	   failure. `view()` ties progress to the element crossing the viewport;
457	   the range runs from just after it appears to a third of the way up, so
458	   it finishes as you arrive at it rather than while it's still an
459	   off-screen sliver. */
460	@supports (animation-timeline: view()) {
461	  .hero-mock-enter {
462	    /* Longhands, not the `animation` shorthand: the shorthand defaults
463	       animation-duration to 0s when it's omitted, which — combined with
464	       fill:both — snapped straight to the end state at every scroll
465	       position (i.e. no visible animation at all). Scroll-driven
466	       animations need `auto`, which maps progress onto animation-range.
467	       The shorthand also resets animation-timeline, so setting these
468	       individually keeps the two declarations from fighting. */
469	    animation-name: hero-mock-in;
470	    animation-duration: auto;
471	    animation-timing-function: linear;
472	    animation-fill-mode: both;
473	    animation-timeline: view();
474	    /* Spans the element's whole entry into the viewport: starts just after
475	       its top edge appears and finishes exactly when it's fully on screen.
476	       Both endpoints in the same phase keeps it predictable (an earlier
477	       `entry 15% cover 38%` mixed phases, which is legal but harder to
478	       reason about and compressed the motion into a shorter scroll). */
479	    animation-range: entry 10% entry 100%;
480	  }
481	}
